/*!
 * Prism stub — ships so the SPA loads without a network request.
 * Replace with the real prism.min.js from https://prismjs.com/ to
 * get syntax highlighting. The stub exposes the surface used by
 * app.js and falls back to HTML escape.
 *
 * LICENSE NOTE: this stub is Apache-2.0 (TML project). The real
 * prism.min.js is MIT; record it in LICENSES-THIRD-PARTY.md once
 * it is vendored.
 */
(function () {
  if (window.Prism) return;
  function esc(s) {
    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }
  window.Prism = {
    languages: { markup: {} },
    highlight: function (code, _grammar, _lang) {
      return esc(code);
    }
  };
})();
